document.addEventListener('DOMContentLoaded',()=>{initCardTilt();initMagneticButtons();});function initCardTilt(){}
function initMagneticButtons(){if(window.matchMedia('(hover: none)').matches)return;const STRENGTH=0.28;const RADIUS=80;document.querySelectorAll('.btn-primary, .btn-outline').forEach(btn=>{let animId;btn.addEventListener('mousemove',e=>{const rect=btn.getBoundingClientRect();const cx=rect.left+rect.width/2;const cy=rect.top+rect.height/2;const dx=e.clientX-cx;const dy=e.clientY-cy;const dist=Math.sqrt(dx*dx+dy*dy);if(dist<RADIUS){const tx=dx*STRENGTH;const ty=dy*STRENGTH;btn.style.transform=`translate(${tx}px, ${ty}px)`;}});btn.addEventListener('mouseleave',()=>{btn.style.transition='transform 0.5s cubic-bezier(0.34,1.56,0.64,1)';btn.style.transform='translate(0,0)';setTimeout(()=>{btn.style.transition='';},500);});});}